const { withSettingsGradle } = require('expo/config-plugins');

const firebasePackages = [
  '@react-native-firebase/app',
  '@react-native-firebase/auth',
];
const marker = '// @generated by with-mock-firebase-autolinking';
const windowsShortPathMarker =
  '// @generated Windows short Expo modules search path';

module.exports = function withMockFirebaseAutolinking(
  expoConfig,
  { excludeFirebase = false } = {},
) {
  return withSettingsGradle(expoConfig, (config) => {
    const excludeArguments = firebasePackages
      .flatMap((packageName) => ['"--exclude"', `"${packageName}"`])
      .join(', ');
    const originalCommand =
      'ex.autolinkLibrariesFromCommand(expoAutolinking.rnConfigCommand)';
    const mockCommand = `${marker}\n    ex.autolinkLibrariesFromCommand(expoAutolinking.rnConfigCommand + [${excludeArguments}])`;
    const expoExclude = `expoAutolinking.exclude = ${JSON.stringify(firebasePackages)}\n`;

    if (excludeFirebase && !config.modResults.contents.includes(marker)) {
      if (!config.modResults.contents.includes(originalCommand)) {
        throw new Error(
          'Could not find the Expo React Native autolinking command in settings.gradle.',
        );
      }

      config.modResults.contents = config.modResults.contents
        .replace(originalCommand, mockCommand)
        .replace(
          'expoAutolinking.useExpoModules()',
          `${expoExclude}expoAutolinking.useExpoModules()`,
        );
    } else if (!excludeFirebase) {
      config.modResults.contents = config.modResults.contents
        .replace(mockCommand, originalCommand)
        .replace(expoExclude, '');
    }

    if (!config.modResults.contents.includes(windowsShortPathMarker)) {
      config.modResults.contents = config.modResults.contents.replace(
        'expoAutolinking.useExpoModules()',
        `${windowsShortPathMarker}
if (System.getProperty("os.name").toLowerCase().contains("windows")) {
  expoAutolinking.searchPaths = [rootDir.toPath().root.resolve("connecto-expo-node-modules").toString()]
}
expoAutolinking.useExpoModules()`,
      );
    }

    return config;
  });
};
